--
-- Name: audit_log_calculate_checksum(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_calculate_checksum() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE
                last_checksum VARCHAR(64);
                record_data TEXT;
            BEGIN
                -- Obtener checksum del último registro (para encadenamiento)
                SELECT checksum INTO last_checksum 
                FROM audit_log 
                ORDER BY created_at DESC, id DESC
                LIMIT 1;
                
                NEW.previous_checksum := COALESCE(last_checksum, 'GENESIS_BLOCK');
                
                -- Construir string para hash
                record_data := concat_ws('|',
                    NEW.id::text,
                    NEW.created_at::text,
                    COALESCE(NEW.user_id::text, 'NULL'),
                    NEW.action_code,
                    NEW.entity_type,
                    COALESCE(NEW.entity_id, 'NULL'),
                    COALESCE(NEW.old_values::text, 'NULL'),
                    COALESCE(NEW.new_values::text, 'NULL'),
                    NEW.previous_checksum
                );
                
                -- Calcular SHA-256 (FIXED: using convert_to instead of cast)
                NEW.checksum := encode(sha256(convert_to(record_data, 'UTF8')), 'hex');
                
                RETURN NEW;
            END;
            $$;


--
-- Name: audit_log_prevent_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_prevent_modification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'AUDIT_LOG_IMMUTABLE: Los registros de auditoría no pueden ser modificados o eliminados. Operación % rechazada para registro %', TG_OP, OLD.id;
END;
$$;


--
-- Name: auto_close_stale_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_close_stale_sessions() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE cash_register_sessions
    SET status = 'CLOSED_AUTO',
        closed_at = NOW(),
        notes = COALESCE(notes, '') || ' | Auto-cerrado por timeout >24h'
    WHERE status = 'OPEN'
      AND opened_at < NOW() - INTERVAL '24 hours';
      
    -- También cerrar los terminales correspondientes
    UPDATE terminals t
    SET status = 'CLOSED',
        current_cashier_id = NULL
    WHERE status = 'OPEN'
      AND NOT EXISTS (
          SELECT 1 FROM cash_register_sessions s
          WHERE s.terminal_id = t.id AND s.status = 'OPEN'
      );
END;
$$;


--
-- Name: check_invoice_duplicate(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_invoice_duplicate(p_supplier_rut character varying, p_invoice_number character varying, p_file_hash character varying) RETURNS TABLE(is_duplicate boolean, duplicate_id uuid, duplicate_status character varying, match_type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Primero buscar por hash exacto del archivo
    RETURN QUERY
    SELECT 
        true AS is_duplicate,
        ip.id AS duplicate_id,
        ip.status AS duplicate_status,
        'FILE_HASH'::VARCHAR(20) AS match_type
    FROM invoice_parsings ip
    WHERE ip.original_file_hash = p_file_hash
    AND ip.status NOT IN ('REJECTED', 'ERROR')
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
    
    -- Luego buscar por RUT + número de factura
    RETURN QUERY
    SELECT 
        true AS is_duplicate,
        ip.id AS duplicate_id,
        ip.status AS duplicate_status,
        'INVOICE_NUMBER'::VARCHAR(20) AS match_type
    FROM invoice_parsings ip
    WHERE ip.supplier_rut = p_supplier_rut
    AND ip.invoice_number = p_invoice_number
    AND ip.status NOT IN ('REJECTED', 'ERROR')
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
    
    -- También verificar en accounts_payable
    RETURN QUERY
    SELECT 
        true AS is_duplicate,
        ap.id AS duplicate_id,
        ap.status AS duplicate_status,
        'ACCOUNTS_PAYABLE'::VARCHAR(20) AS match_type
    FROM accounts_payable ap
    JOIN suppliers s ON ap.supplier_id = s.id
    WHERE s.rut = p_supplier_rut
    AND ap.invoice_number = p_invoice_number
    AND ap.status != 'CANCELLED'
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
    
    -- No es duplicado
    RETURN QUERY SELECT false, NULL::UUID, NULL::VARCHAR(20), NULL::VARCHAR(20);
END;
$$;


--
-- Name: FUNCTION check_invoice_duplicate(p_supplier_rut character varying, p_invoice_number character varying, p_file_hash character varying); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_invoice_duplicate(p_supplier_rut character varying, p_invoice_number character varying, p_file_hash character varying) IS 'Detecta si una factura ya fue procesada';


--
-- Name: create_playground(regclass, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_playground(src_hypertable regclass, compressed boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
    _table_name NAME;
    _schema_name NAME;
    _src_relation NAME;
    _playground_table_fqn NAME;
    _chunk_name NAME;
    _chunk_check BOOL;
    _playground_schema_check BOOL;
    _next_id INTEGER;
    _dimension TEXT;
    _interval TEXT;
    _segmentby_cols TEXT;
    _orderby_cols TEXT;
BEGIN
    SELECT EXISTS(SELECT 1 FROM information_schema.schemata
    WHERE schema_name = 'tsdb_playground') INTO _playground_schema_check;

    IF NOT _playground_schema_check THEN
        RAISE EXCEPTION '"tsdb_playground" schema must be created before running this';
    END IF;

    -- get schema and table name
    SELECT n.nspname, c.relname INTO _schema_name, _table_name
    FROM pg_class c
    INNER JOIN pg_namespace n ON (n.oid = c.relnamespace)
    INNER JOIN timescaledb_information.hypertables i ON (i.hypertable_name = c.relname )
    WHERE c.oid = src_hypertable;

    IF _table_name IS NULL THEN
        RAISE EXCEPTION '% is not a hypertable', src_hypertable;
    END IF;

    SELECT EXISTS(SELECT 1 FROM timescaledb_information.chunks WHERE hypertable_name = _table_name AND hypertable_schema = _schema_name) INTO _chunk_check;

    IF NOT _chunk_check THEN
        RAISE EXCEPTION '% has no chunks for playground testing', src_hypertable;
    END IF;

    EXECUTE pg_catalog.format($$ CREATE SEQUENCE IF NOT EXISTS tsdb_playground.%I $$, _table_name||'_seq');
    SELECT pg_catalog.nextval('tsdb_playground.' || pg_catalog.quote_ident(_table_name || '_seq')) INTO _next_id;

    SELECT pg_catalog.format('%I.%I', _schema_name, _table_name) INTO _src_relation;

    SELECT pg_catalog.format('tsdb_playground.%I', _table_name || '_' || _next_id::text) INTO _playground_table_fqn;

    EXECUTE pg_catalog.format(
        $$ CREATE TABLE %s (like %s including comments including constraints including defaults including indexes) $$
        , _playground_table_fqn, _src_relation
        );

    -- get dimension column from src ht for partitioning playground ht
    SELECT column_name, time_interval INTO _dimension, _interval FROM timescaledb_information.dimensions WHERE hypertable_name = _table_name AND hypertable_schema = _schema_name LIMIT 1;

    PERFORM public.create_hypertable(_playground_table_fqn::REGCLASS, _dimension::NAME, chunk_time_interval := _interval::interval);

    -- Ideally, it should pick up the latest complete chunk (second last chunk) from this hypertable.
    -- If num_chunks > 1 then it will get true, converted into 1, taking the second row, otherwise it'll get false converted to 0 and get no offset.
    SELECT
        format('%I.%I',chunk_schema,chunk_name)
    INTO STRICT
        _chunk_name
    FROM
        timescaledb_information.chunks
    WHERE
        hypertable_schema = _schema_name AND
        hypertable_name = _table_name
    ORDER BY
        chunk_creation_time DESC OFFSET (
            SELECT
                (num_chunks > 1)::integer
            FROM timescaledb_information.hypertables
            WHERE
                hypertable_name = _table_name)
    LIMIT 1;
	EXECUTE pg_catalog.format($$ INSERT INTO %s SELECT * FROM %s $$, _playground_table_fqn, _chunk_name);

    IF compressed THEN
        --retrieve compression settings from source hypertable
        SELECT segmentby INTO _segmentby_cols
        FROM timescaledb_information.hypertable_compression_settings
        WHERE hypertable = _src_relation::REGCLASS;

		SELECT orderby INTO _orderby_cols
		FROM timescaledb_information.hypertable_compression_settings
        WHERE hypertable = _src_relation::REGCLASS;

        IF (_segmentby_cols IS NOT NULL) AND (_orderby_cols IS NOT NULL) THEN
            EXECUTE pg_catalog.format(
                $$ ALTER TABLE %s SET(timescaledb.compress, timescaledb.compress_segmentby = %I, timescaledb.compress_orderby = %I) $$
                , _playground_table_fqn, _segmentby_cols, _orderby_cols
                );
        ELSE
            EXECUTE pg_catalog.format(
                $$ ALTER TABLE %s SET(timescaledb.compress) $$
                , _playground_table_fqn
                );
        END IF;
        -- get playground chunk and compress
    PERFORM public.compress_chunk(public.show_chunks(_playground_table_fqn::REGCLASS));
    END IF;

	RETURN _playground_table_fqn;
END
$_$;


--
-- Name: fn_audit_log(uuid, character varying, character varying, uuid, uuid, uuid, character varying, character varying, character varying, jsonb, jsonb, jsonb, text, uuid, inet, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_log(p_user_id uuid, p_user_name character varying, p_user_role character varying, p_session_id uuid, p_terminal_id uuid, p_location_id uuid, p_action_code character varying, p_entity_type character varying, p_entity_id character varying, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb, p_justification text DEFAULT NULL::text, p_authorized_by uuid DEFAULT NULL::uuid, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_audit_id UUID;
    v_requires_justification BOOLEAN;
BEGIN
    -- Verificar si la acción requiere justificación
    SELECT requires_justification INTO v_requires_justification
    FROM audit_action_catalog
    WHERE code = p_action_code;
    
    IF v_requires_justification AND (p_justification IS NULL OR LENGTH(TRIM(p_justification)) < 10) THEN
        RAISE EXCEPTION 'La acción % requiere justificación de al menos 10 caracteres', p_action_code;
    END IF;
    
    -- Insertar registro
        user_id, user_name, user_role,
        session_id, terminal_id, location_id,
        action_code, entity_type, entity_id,
        old_values, new_values, metadata,
        justification, authorized_by,
        ip_address, user_agent, request_id
    ) VALUES (
        p_user_id, p_user_name, p_user_role,
        p_session_id, p_terminal_id, p_location_id,
        p_action_code, p_entity_type, p_entity_id,
        p_old_values, p_new_values, p_metadata,
        p_justification, p_authorized_by,
        p_ip_address, p_user_agent, p_request_id
    )
    RETURNING id INTO v_audit_id;
    
    RETURN v_audit_id;
END;
$$;


--
-- Name: FUNCTION fn_audit_log(p_user_id uuid, p_user_name character varying, p_user_role character varying, p_session_id uuid, p_terminal_id uuid, p_location_id uuid, p_action_code character varying, p_entity_type character varying, p_entity_id character varying, p_old_values jsonb, p_new_values jsonb, p_metadata jsonb, p_justification text, p_authorized_by uuid, p_ip_address inet, p_user_agent text, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_audit_log(p_user_id uuid, p_user_name character varying, p_user_role character varying, p_session_id uuid, p_terminal_id uuid, p_location_id uuid, p_action_code character varying, p_entity_type character varying, p_entity_id character varying, p_old_values jsonb, p_new_values jsonb, p_metadata jsonb, p_justification text, p_authorized_by uuid, p_ip_address inet, p_user_agent text, p_request_id uuid) IS 'Función helper para insertar registros de auditoría con validación';


--
-- Name: fn_calculate_theoretical_amount(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_calculate_theoretical_amount(p_session_id uuid) RETURNS TABLE(opening_amount numeric, cash_sales_total numeric, cash_movements_in numeric, cash_movements_out numeric, theoretical_total numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(s.opening_amount, 0)::NUMERIC AS opening_amount,
        COALESCE((
            SELECT SUM(total_amount) 
            FROM sales 
            WHERE terminal_id = s.terminal_id 
            AND payment_method = 'CASH'
            AND timestamp BETWEEN s.opened_at AND COALESCE(s.closed_at, NOW())
        ), 0)::NUMERIC AS cash_sales_total,
        COALESCE((
            SELECT SUM(amount) 
            FROM cash_movements 
            WHERE session_id = s.id 
            AND type IN ('EXTRA_INCOME')
        ), 0)::NUMERIC AS cash_movements_in,
        COALESCE((
            SELECT SUM(amount) 
            FROM cash_movements 
            WHERE session_id = s.id 
            AND type IN ('WITHDRAWAL', 'EXPENSE')
        ), 0)::NUMERIC AS cash_movements_out,
        (
            COALESCE(s.opening_amount, 0) +
            COALESCE((SELECT SUM(total_amount) FROM sales WHERE terminal_id = s.terminal_id AND payment_method = 'CASH' AND timestamp BETWEEN s.opened_at AND COALESCE(s.closed_at, NOW())), 0) +
            COALESCE((SELECT SUM(amount) FROM cash_movements WHERE session_id = s.id AND type IN ('EXTRA_INCOME')), 0) -
            COALESCE((SELECT SUM(amount) FROM cash_movements WHERE session_id = s.id AND type IN ('WITHDRAWAL', 'EXPENSE')), 0)
        )::NUMERIC AS theoretical_total
    FROM cash_register_sessions s
    WHERE s.id = p_session_id;
END;
$$;


--
-- Name: fn_detect_reconciliation_patterns(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_detect_reconciliation_patterns(p_user_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(pattern_type character varying, occurrence_count bigint, total_amount numeric, avg_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    -- Detectar faltantes consecutivos
    SELECT 
        'CONSECUTIVE_SHORTAGES'::VARCHAR AS pattern_type,
        COUNT(*)::BIGINT AS occurrence_count,
        SUM(ABS(cr.difference))::NUMERIC AS total_amount,
        AVG(ABS(cr.difference))::NUMERIC AS avg_amount
    FROM cash_reconciliations cr
    WHERE cr.created_by = p_user_id
    AND cr.difference < -500
    AND cr.created_at > NOW() - (p_days || ' days')::INTERVAL
    HAVING COUNT(*) >= 3
    
    UNION ALL
    
    -- Detectar mismo monto repetido
    SELECT 
        'SAME_AMOUNT_SHORTAGE'::VARCHAR AS pattern_type,
        COUNT(*)::BIGINT AS occurrence_count,
        SUM(ABS(cr.difference))::NUMERIC AS total_amount,
        AVG(ABS(cr.difference))::NUMERIC AS avg_amount
    FROM cash_reconciliations cr
    WHERE cr.created_by = p_user_id
    AND cr.difference < -500
    AND cr.created_at > NOW() - (p_days || ' days')::INTERVAL
    GROUP BY ROUND(cr.difference, -2) -- Agrupar por centenas
    HAVING COUNT(*) >= 2;
END;
$$;


--
-- Name: fn_reconciliation_auto_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reconciliation_auto_alert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alert_type VARCHAR(30);
    v_severity VARCHAR(10);
BEGIN
    -- Solo crear alertas para diferencias significativas
    IF ABS(NEW.difference) <= 500 THEN
        RETURN NEW;
    END IF;
    
    -- Determinar tipo y severidad de alerta
    IF NEW.difference < -5000 THEN
        v_alert_type := 'CRITICAL_SHORTAGE';
        v_severity := 'CRITICAL';
    ELSIF NEW.difference < -1000 THEN
        v_alert_type := 'MAJOR_SHORTAGE';
        v_severity := 'HIGH';
    ELSIF NEW.difference < 0 THEN
        v_alert_type := 'MINOR_SHORTAGE';
        v_severity := 'MEDIUM';
    ELSIF NEW.difference > 5000 THEN
        v_alert_type := 'SUSPICIOUS_SURPLUS';
        v_severity := 'HIGH';
    ELSE
        v_alert_type := 'SUSPICIOUS_SURPLUS';
        v_severity := 'MEDIUM';
    END IF;
    
    -- Crear alerta
        reconciliation_id,
        alert_type,
        severity
    ) VALUES (
        NEW.id,
        v_alert_type,
        v_severity
    );
    
    RETURN NEW;
END;
$$;


--
-- Name: mark_overdue_accounts_payable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_overdue_accounts_payable() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    UPDATE accounts_payable
    SET status = 'OVERDUE', updated_at = NOW()
    WHERE due_date < CURRENT_DATE
    AND status IN ('PENDING', 'PARTIAL');
    
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$$;


--
-- Name: FUNCTION mark_overdue_accounts_payable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_overdue_accounts_payable() IS 'Ejecutar diariamente para marcar cuentas vencidas';


--
-- Name: prevent_double_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_double_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'OPEN' AND OLD.status = 'OPEN' AND NEW.current_cashier_id IS DISTINCT FROM OLD.current_cashier_id THEN
         RAISE EXCEPTION 'Terminal ya está abierto por otro cajero. Use forceClose() si es necesario.';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: search_products_fuzzy(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_products_fuzzy(search_term text, limit_count integer DEFAULT 5) RETURNS TABLE(id text, sku text, name text, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id::TEXT, 
        p.sku::TEXT, 
        p.name::TEXT, 
        similarity(p.name, search_term) as sim
    FROM products p
    WHERE 
        p.name % search_term  -- Operator % uses strict threshold (default 0.3)
        OR p.sku ILIKE '%' || search_term || '%'
    ORDER BY sim DESC
    LIMIT limit_count;
END;
$$;


--
-- Name: update_account_payable_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_account_payable_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Actualizar paid_amount en accounts_payable
    UPDATE accounts_payable
    SET 
        paid_amount = COALESCE((
            SELECT SUM(amount) 
            FROM accounts_payable_payments 
            WHERE account_payable_id = NEW.account_payable_id 
            AND status = 'COMPLETED'
        ), 0),
        updated_at = NOW()
    WHERE id = NEW.account_payable_id;
    
    -- Actualizar status basado en pagos
    UPDATE accounts_payable
    SET status = CASE
        WHEN paid_amount >= total_amount THEN 'PAID'
        WHEN paid_amount > 0 THEN 'PARTIAL'
        WHEN due_date < CURRENT_DATE AND status NOT IN ('PAID', 'CANCELLED') THEN 'OVERDUE'
        ELSE status
    END
    WHERE id = NEW.account_payable_id;
    
    RETURN NEW;
END;
$$;


--
-- Name: update_terminal_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_terminal_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: create_bare_readonly_role(text, text); Type: FUNCTION; Schema: timescale_functions; Owner: -
--

CREATE FUNCTION timescale_functions.create_bare_readonly_role(role_name text, role_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  -- Sanity checks
  IF pg_catalog.current_setting('server_version_num')::integer < 160000 THEN
    RAISE EXCEPTION 'this function should be called only on pg version 16 and higher, your version is %s', pg_catalog.version();
  END IF;

  IF pg_catalog.to_regrole(role_name) IS NOT NULL THEN
    RAISE EXCEPTION 'role % already exists', role_name;
  END IF;

  IF pg_catalog.to_regrole('bare_roles') IS NULL THEN
    RAISE EXCEPTION 'role bare_roles does not exist';
  END IF;

  -- Create the role with password
  EXECUTE pg_catalog.format('CREATE ROLE %I LOGIN PASSWORD %L', role_name, role_password);

  -- Add to the bare_roles tracking group
  EXECUTE pg_catalog.format('GRANT bare_roles TO %I', role_name);

  -- Set the read-only GUC
  EXECUTE pg_catalog.format('ALTER ROLE %I SET tsdb_admin.read_only_role = true', role_name);
END;
$$;


--
-- Name: FUNCTION create_bare_readonly_role(role_name text, role_password text); Type: COMMENT; Schema: timescale_functions; Owner: -
--

COMMENT ON FUNCTION timescale_functions.create_bare_readonly_role(role_name text, role_password text) IS 'Creates a bare role (not a member of or administered by tsdbadmin) that can be granted tsdbadmin privileges without circular dependency';


--
-- Name: delete_bare_readonly_role(text); Type: FUNCTION; Schema: timescale_functions; Owner: -
--

CREATE FUNCTION timescale_functions.delete_bare_readonly_role(role_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  is_member BOOLEAN;
BEGIN
  -- Sanity checks
  IF pg_catalog.current_setting('server_version_num')::integer < 160000 THEN
    RAISE EXCEPTION 'this function should be called only on pg version 16 and higher, your version is %s', pg_catalog.version();
  END IF;

  IF pg_catalog.to_regrole(role_name) IS NULL THEN
    RAISE EXCEPTION 'role % does not exist', role_name;
  END IF;

  IF pg_catalog.to_regrole('bare_roles') IS NULL THEN
    RAISE EXCEPTION 'role bare_roles does not exist';
  END IF;

  -- Verify the role is a member of bare_roles before deletion
  SELECT pg_catalog.pg_has_role(role_name, 'bare_roles', 'USAGE') INTO is_member;

  IF NOT is_member THEN
    RAISE EXCEPTION 'role % is not a bare read-only role (not a member of bare_roles)', role_name;
  END IF;

  -- Drop the role (this will fail if the role owns objects or has dependent privileges)
  EXECUTE pg_catalog.format('DROP ROLE %I', role_name);
END;
$$;


--
-- Name: FUNCTION delete_bare_readonly_role(role_name text); Type: COMMENT; Schema: timescale_functions; Owner: -
--

COMMENT ON FUNCTION timescale_functions.delete_bare_readonly_role(role_name text) IS 'Safely deletes a bare role (not a member of or administered by tsdbadmin) by verifying it is a member of the bare_roles tracking group';


--
-- Name: grant_tsdbadmin_to_role(text); Type: FUNCTION; Schema: timescale_functions; Owner: -
--

CREATE FUNCTION timescale_functions.grant_tsdbadmin_to_role(rolename text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF pg_catalog.current_setting('server_version_num')::integer < 160000 THEN
    RAISE EXCEPTION 'this function should be called only on pg version 16 and higher, your version is %s', pg_catalog.version();
  END IF;

  IF pg_catalog.to_regrole(rolename) IS NULL THEN
    RAISE EXCEPTION 'role %s does not exist', rolename;
  END IF;

  IF pg_catalog.to_regrole('tsdbadmin') IS NULL THEN
    RAISE EXCEPTION 'role tsdbadmin does not exist';
  END IF;

  EXECUTE pg_catalog.format('GRANT tsdbadmin TO %I WITH INHERIT TRUE, SET TRUE', rolename);
END;
$$;


--
-- Name: FUNCTION grant_tsdbadmin_to_role(rolename text); Type: COMMENT; Schema: timescale_functions; Owner: -
--

COMMENT ON FUNCTION timescale_functions.grant_tsdbadmin_to_role(rolename text) IS 'This role grants tsdbadmin (database owner) to another role';


--
-- Name: move_createrole(regrole, regrole); Type: FUNCTION; Schema: timescale_functions; Owner: -
--

CREATE FUNCTION timescale_functions.move_createrole(old_role regrole, new_role regrole) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  role_member RECORD;
BEGIN
  -- sanity checks
  IF pg_catalog.current_setting('server_version_num')::integer < 160000 THEN
    RAISE EXCEPTION 'this function should be called only on pg version 16 and higher, your version is %s', pg_catalog.version();
  END IF;

  IF pg_catalog.to_regrole(old_role::text) IS NULL
  THEN
    RAISE EXCEPTION 'old role % does not exist', old_role;
  END IF;
  IF pg_catalog.to_regrole(new_role::text) IS NULL
  THEN
    RAISE EXCEPTION 'new role % does not exist', new_role;
  END IF;

  IF (SELECT rolcreaterole FROM pg_catalog.pg_roles where rolname = old_role::text) IS FALSE
  THEN
    RAISE EXCEPTION 'role % does is not CREATEROLE', old_role;
  END IF;
  IF (SELECT rolcreaterole FROM pg_catalog.pg_roles where rolname = new_role::text) IS TRUE
  THEN
    RAISE EXCEPTION 'role % is already CREATEROLE', new_role;
  END IF;
  -- for each member role of the old role, move the members to the new role
  -- so that new role will be able to administer roles created by the old role
  FOR role_member IN
    SELECT
      roleid::regrole,
      admin_option,
      inherit_option,
      set_option
  FROM
    pg_catalog.pg_auth_members
  WHERE
    member = old_role AND
    roleid::regrole != old_role AND
    roleid::regrole != new_role
  LOOP
      EXECUTE format(
          'GRANT %I TO %I WITH %s, %s, %s',
          role_member.roleid,
          new_role,
          CASE WHEN role_member.admin_option THEN 'ADMIN OPTION' ELSE 'ADMIN FALSE' END,
          CASE WHEN role_member.inherit_option THEN 'INHERIT TRUE' ELSE 'INHERIT FALSE' END,
          CASE WHEN role_member.set_option THEN 'SET TRUE' ELSE 'SET FALSE' END
              );
      EXECUTE format('REVOKE %I FROM %I', role_member.roleid, old_role
              );
    END LOOP;
    -- without revoking new role from the old one, the roles created by the new role
    -- will still contain (indirectly) the old one, and the old one (tsdbadmin) would
    -- be non-grantable to them.
    EXECUTE format('REVOKE %I FROM %I', new_role, old_role);

    EXECUTE format('ALTER ROLE %I CREATEROLE', new_role);
    EXECUTE format('ALTER ROLE %I NOCREATEROLE', old_role);
    -- make sure new role can transfer its CREATEROLE, but old role not.
    EXECUTE format('GRANT EXECUTE ON FUNCTION timescale_functions.move_createrole TO %I', new_role);
    EXECUTE format('REVOKE EXECUTE ON FUNCTION timescale_functions.move_createrole FROM %I', old_role);
    EXECUTE format('REVOKE EXECUTE ON FUNCTION timescale_functions.grant_tsdbadmin_to_role FROM %I', old_role);
    EXECUTE format('GRANT EXECUTE ON FUNCTION timescale_functions.grant_tsdbadmin_to_role TO %I', new_role);
    EXECUTE format('REVOKE EXECUTE ON FUNCTION timescale_functions.revoke_tsdbadmin_from_role FROM %I', old_role);
    EXECUTE format('GRANT EXECUTE ON FUNCTION timescale_functions.revoke_tsdbadmin_from_role TO %I', new_role);
END;
$$;


--
-- Name: FUNCTION move_createrole(old_role regrole, new_role regrole); Type: COMMENT; Schema: timescale_functions; Owner: -
--

COMMENT ON FUNCTION timescale_functions.move_createrole(old_role regrole, new_role regrole) IS 'This function allows moving createrole privileges between existing createrole, and another user';


--
-- Name: revoke_tsdbadmin_from_role(text); Type: FUNCTION; Schema: timescale_functions; Owner: -
--

CREATE FUNCTION timescale_functions.revoke_tsdbadmin_from_role(rolename text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF pg_catalog.current_setting('server_version_num')::integer < 160000 THEN
    RAISE EXCEPTION 'this function should be called only on pg version 16 and higher, your version is %s', pg_catalog.version();
  END IF;

  IF pg_catalog.to_regrole(rolename) IS NULL THEN
    RAISE EXCEPTION 'role %s does not exist', rolename;
  END IF;

  IF pg_catalog.to_regrole('tsdbadmin') IS NULL THEN
    RAISE EXCEPTION 'role tsdbadmin does not exist';
  END IF;

  EXECUTE pg_catalog.format('REVOKE tsdbadmin FROM %I', rolename);
END;
$$;


--
-- Name: FUNCTION revoke_tsdbadmin_from_role(rolename text); Type: COMMENT; Schema: timescale_functions; Owner: -
--

COMMENT ON FUNCTION timescale_functions.revoke_tsdbadmin_from_role(rolename text) IS 'This role revokes tsdbadmin (database owner) to another role';


