CREATE TABLE public.sales (
    id uuid NOT NULL,
    "timestamp" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    total integer NOT NULL,
    payment_method character varying(50) NOT NULL,
    user_id character varying(50),
    customer_rut character varying(20),
    location_id uuid NOT NULL,
    terminal_id uuid NOT NULL,
    dte_status character varying(50),
    total_amount numeric(15,2) NOT NULL,
    dte_folio integer,
    session_id uuid NOT NULL,
    customer_name character varying(255),
    subtotal numeric DEFAULT 0 NOT NULL,
    discount_amount numeric DEFAULT 0,
    points_discount numeric DEFAULT 0,
    transfer_id character varying(100),
    notes text,
    status character varying(20) DEFAULT 'COMPLETED'::character varying NOT NULL,
    dte_type character varying(20),
    queue_ticket_id uuid,
    CONSTRAINT chk_sale_math_consistency CHECK (((subtotal >= (0)::numeric) AND (discount_amount >= (0)::numeric) AND (points_discount >= (0)::numeric) AND (total_amount >= (0)::numeric) AND (subtotal >= (discount_amount + points_discount)))),
    CONSTRAINT chk_sales_subtotal_non_negative CHECK (((subtotal >= (0)::numeric) OR (subtotal IS NULL))),
    CONSTRAINT chk_sales_total_non_negative CHECK (((total_amount >= (0)::numeric) OR (total_amount IS NULL)))
);


