--
-- Name: sale_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_items (
    id uuid NOT NULL,
    sale_id uuid NOT NULL,
    batch_id uuid,
    quantity integer NOT NULL,
    unit_price numeric(15,2),
    total_price numeric(15,2) NOT NULL,
    refunded_quantity integer DEFAULT 0 NOT NULL,
    discount_amount numeric DEFAULT 0,
    product_name text,
    "timestamp" timestamp without time zone NOT NULL,
    CONSTRAINT chk_refund_limit CHECK (((refunded_quantity >= 0) AND (refunded_quantity <= quantity))),
    CONSTRAINT chk_refunded_quantity_valid CHECK (((refunded_quantity IS NULL) OR (refunded_quantity >= 0))),
    CONSTRAINT chk_sale_items_quantity_positive CHECK (((quantity > 0) OR (quantity IS NULL)))
);


--
-- Name: COLUMN sale_items.refunded_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_items.refunded_quantity IS 'Cantidad del ítem que ha sido devuelta/reembolsada';


