--
-- Name: accounts_payable; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts_payable (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    supplier_id uuid NOT NULL,
    invoice_number character varying(50),
    invoice_type character varying(20) DEFAULT 'FACTURA'::character varying,
    issue_date date,
    reception_date date DEFAULT CURRENT_DATE,
    due_date date,
    net_amount numeric(15,2) DEFAULT 0 NOT NULL,
    tax_amount numeric(15,2) DEFAULT 0 NOT NULL,
    other_taxes numeric(15,2) DEFAULT 0,
    discount_amount numeric(15,2) DEFAULT 0,
    total_amount numeric(15,2) NOT NULL,
    paid_amount numeric(15,2) DEFAULT 0,
    balance numeric(15,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    status character varying(20) DEFAULT 'PENDING'::character varying,
    location_id uuid,
    purchase_order_id uuid,
    invoice_parsing_id uuid,
    reception_id uuid,
    expense_category character varying(50) DEFAULT 'INVENTORY'::character varying,
    notes text,
    attachments jsonb,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    approved_by uuid,
    approved_at timestamp with time zone,
    CONSTRAINT chk_ap_amounts CHECK (((net_amount >= (0)::numeric) AND (tax_amount >= (0)::numeric) AND (total_amount >= (0)::numeric))),
    CONSTRAINT chk_ap_paid CHECK (((paid_amount >= (0)::numeric) AND (paid_amount <= total_amount))),
    CONSTRAINT chk_ap_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PARTIAL'::character varying, 'PAID'::character varying, 'OVERDUE'::character varying, 'CANCELLED'::character varying, 'DISPUTED'::character varying])::text[])))
);


--
-- Name: TABLE accounts_payable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.accounts_payable IS 'Cuentas por pagar a proveedores - Módulo de Tesorería';


--
-- Name: COLUMN accounts_payable.balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts_payable.balance IS 'Saldo pendiente calculado automáticamente';


--
-- Name: COLUMN accounts_payable.expense_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts_payable.expense_category IS 'Categoría para reportes financieros';


--
-- Name: accounts_payable_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts_payable_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_payable_id uuid NOT NULL,
    payment_date date DEFAULT CURRENT_DATE NOT NULL,
    amount numeric(15,2) NOT NULL,
    payment_method character varying(30) NOT NULL,
    reference_number character varying(100),
    bank_account_id uuid,
    status character varying(20) DEFAULT 'COMPLETED'::character varying,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT chk_app_amount CHECK ((amount > (0)::numeric)),
    CONSTRAINT chk_app_method CHECK (((payment_method)::text = ANY ((ARRAY['TRANSFER'::character varying, 'CHECK'::character varying, 'CASH'::character varying, 'CREDIT_NOTE'::character varying])::text[])))
);


--
-- Name: TABLE accounts_payable_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.accounts_payable_payments IS 'Registro de pagos realizados a cuentas por pagar';


