    retention_days integer DEFAULT 2555,
    CONSTRAINT audit_action_catalog_category_check CHECK (((category)::text = ANY ((ARRAY['FINANCIAL'::character varying, 'SECURITY'::character varying, 'OPERATIONAL'::character varying, 'COMPLIANCE'::character varying, 'SYSTEM'::character varying, 'AI'::character varying, 'INVENTORY'::character varying])::text[]))),
    CONSTRAINT audit_action_catalog_severity_check CHECK (((severity)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[])))
);


