--
-- Name: cash_reconciliations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_reconciliations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    terminal_id uuid NOT NULL,
    location_id uuid NOT NULL,
    theoretical_amount numeric(15,2) NOT NULL,
    opening_amount numeric(15,2) NOT NULL,
    cash_sales_total numeric(15,2) DEFAULT 0 NOT NULL,
    cash_movements_in numeric(15,2) DEFAULT 0 NOT NULL,
    cash_movements_out numeric(15,2) DEFAULT 0 NOT NULL,
    declared_amount numeric(15,2) NOT NULL,
    difference numeric(15,2) GENERATED ALWAYS AS ((declared_amount - theoretical_amount)) STORED,
    difference_type character varying(20) GENERATED ALWAYS AS (
CASE
    WHEN ((declared_amount - theoretical_amount) > (0)::numeric) THEN 'SURPLUS'::text
    WHEN ((declared_amount - theoretical_amount) < (0)::numeric) THEN 'SHORTAGE'::text
    ELSE 'BALANCED'::text
END) STORED,
    physical_count jsonb,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    requires_justification boolean GENERATED ALWAYS AS ((abs((declared_amount - theoretical_amount)) > (500)::numeric)) STORED,
    created_at timestamp with time zone DEFAULT now(),
    created_by uuid NOT NULL,
    approved_at timestamp with time zone,
    approved_by uuid,
    approval_notes text,
    CONSTRAINT cash_reconciliations_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'ESCALATED'::character varying, 'UNDER_INVESTIGATION'::character varying])::text[])))
);


--
-- Name: TABLE cash_reconciliations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.cash_reconciliations IS 'Registro de conciliaciones de arqueo de caja';


--
-- Name: COLUMN cash_reconciliations.theoretical_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cash_reconciliations.theoretical_amount IS 'Monto esperado calculado: apertura + ventas_efectivo + ingresos - egresos';


--
-- Name: COLUMN cash_reconciliations.difference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cash_reconciliations.difference IS 'Diferencia: declarado - teórico (positivo=sobrante, negativo=faltante)';


--
