    parsed_items jsonb DEFAULT '[]'::jsonb NOT NULL,
    document_notes text,
    raw_ai_response jsonb,
    ai_provider character varying(20),
    ai_model character varying(50),
    processing_time_ms integer,
    confidence_score numeric(3,2),
    validation_warnings jsonb DEFAULT '[]'::jsonb,
    status character varying(20) DEFAULT 'PENDING'::character varying,
    total_items integer DEFAULT 0,
    mapped_items integer DEFAULT 0,
    unmapped_items integer DEFAULT 0,
    supplier_id uuid,
    supplier_created boolean DEFAULT false,
    account_payable_id uuid,
    reception_id uuid,
    original_file_type character varying(10),
    original_file_name character varying(200),
    original_file_size integer,
    original_file_hash character varying(64),
    location_id uuid,
    created_by character varying,
    created_at timestamp with time zone DEFAULT now(),
    validated_by character varying,
    validated_at timestamp with time zone,
    processed_by character varying,
    processed_at timestamp with time zone,
    rejected_by character varying,
    rejected_at timestamp with time zone,
    rejection_reason text,
    error_message text,
    error_details jsonb,
    supplier_phone text,
    supplier_email text,
    supplier_website text,
    supplier_activity text,
    supplier_fantasy_name text,
    original_file_data bytea,
    CONSTRAINT chk_ip_amounts CHECK ((((net_amount IS NULL) OR (net_amount >= (0)::numeric)) AND ((tax_amount IS NULL) OR (tax_amount >= (0)::numeric)) AND ((total_amount IS NULL) OR (total_amount >= (0)::numeric)))),
    CONSTRAINT chk_ip_confidence CHECK (((confidence_score IS NULL) OR ((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric)))),
    CONSTRAINT chk_ip_document_type CHECK (((document_type)::text = ANY ((ARRAY['FACTURA'::character varying, 'BOLETA'::character varying, 'GUIA_DESPACHO'::character varying, 'NOTA_CREDITO'::character varying])::text[]))),
    CONSTRAINT chk_ip_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'VALIDATED'::character varying, 'MAPPING'::character varying, 'PROCESSING'::character varying, 'COMPLETED'::character varying, 'PARTIAL'::character varying, 'ERROR'::character varying, 'REJECTED'::character varying])::text[])))
);


