    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT reconciliation_alerts_alert_type_check CHECK (((alert_type)::text = ANY ((ARRAY['MINOR_SHORTAGE'::character varying, 'MAJOR_SHORTAGE'::character varying, 'CRITICAL_SHORTAGE'::character varying, 'SUSPICIOUS_SURPLUS'::character varying, 'PATTERN_DETECTED'::character varying, 'UNJUSTIFIED'::character varying, 'ESCALATED'::character varying])::text[]))),
    CONSTRAINT reconciliation_alerts_severity_check CHECK (((severity)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT reconciliation_alerts_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'ACKNOWLEDGED'::character varying, 'RESOLVED'::character varying, 'ESCALATED'::character varying])::text[])))
);


