    validated_at timestamp with time zone,
    validated_by uuid,
    validation_status character varying(20),
    validation_notes text,
    CONSTRAINT reconciliation_justifications_description_check CHECK ((length(description) >= 20)),
    CONSTRAINT reconciliation_justifications_justification_type_check CHECK (((justification_type)::text = ANY ((ARRAY['COUNTING_ERROR'::character varying, 'CHANGE_GIVEN_WRONG'::character varying, 'SALE_NOT_RECORDED'::character varying, 'MOVEMENT_NOT_RECORDED'::character varying, 'THEFT_SUSPECTED'::character varying, 'SYSTEM_ERROR'::character varying, 'COINS_STUCK'::character varying, 'ROUNDING'::character varying, 'VOID_NOT_PROCESSED'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT reconciliation_justifications_validation_status_check CHECK (((validation_status)::text = ANY ((ARRAY['ACCEPTED'::character varying, 'REJECTED'::character varying, 'PARTIAL'::character varying])::text[])))
);


