    location_id uuid,
    name text NOT NULL,
    status text DEFAULT 'CLOSED'::text,
    current_cashier_id character varying(50),
    created_at timestamp without time zone DEFAULT now(),
    is_active boolean DEFAULT true,
    deleted_at timestamp without time zone,
    config jsonb DEFAULT '{}'::jsonb,
    allowed_users text[] DEFAULT '{}'::text[],
    updated_at timestamp without time zone DEFAULT now(),
    module_number character varying(50),
    CONSTRAINT chk_terminal_status CHECK ((status = ANY (ARRAY['OPEN'::text, 'CLOSED'::text, 'MAINTENANCE'::text, 'DELETED'::text])))
);


