--
-- Name: time_off_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.time_off_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    type text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    approved_by text,
    reason text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT valid_dates CHECK ((end_date >= start_date))
);


--
-- Name: treasury_remittances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.treasury_remittances (
    id uuid NOT NULL,
    location_id uuid,
    source_terminal_id uuid,
    amount numeric(12,2) NOT NULL,
    status text NOT NULL,
    created_by uuid,
    received_by uuid,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    shift_start timestamp without time zone,
    shift_end timestamp without time zone,
    cash_count_diff numeric(12,2) DEFAULT 0,
    notes text,
    CONSTRAINT treasury_remittances_status_check CHECK ((status = ANY (ARRAY['PENDING_RECEIPT'::text, 'RECEIVED'::text])))
