--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id character varying(50) DEFAULT gen_random_uuid() NOT NULL,
    rut character varying(20) NOT NULL,
    name character varying(150) NOT NULL,
    role character varying(50) NOT NULL,
    access_pin text DEFAULT '9080'::character varying,
    status character varying(20) DEFAULT 'ACTIVE'::character varying,
    job_title character varying(100),
    email character varying(255),
    phone character varying(50),
    address text,
    biometric_credentials jsonb DEFAULT '[]'::jsonb,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    last_login timestamp without time zone,
    assigned_location_id uuid,
    base_salary integer,
    pin_hash character varying(255),
    afp character varying(50) DEFAULT 'MODELO'::character varying,
    isapre character varying(50) DEFAULT 'FONASA'::character varying,
    weekly_hours integer DEFAULT 45,
    health_system character varying(100),
    last_active_at timestamp without time zone DEFAULT now(),
    token_version integer DEFAULT 1,
    current_context_data jsonb DEFAULT '{}'::jsonb,
    password text,
    access_pin_hash character varying(60),
    last_login_at timestamp without time zone,
    last_login_ip character varying(45),
    is_active boolean DEFAULT true,
    allowed_modules text[]
);


--
-- Name: v_accounts_payable_aging; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_accounts_payable_aging AS
 SELECT s.id AS supplier_id,
    COALESCE(s.fantasy_name, s.business_name) AS supplier_name,
    s.rut AS supplier_rut,
    count(*) AS total_invoices,
    sum(ap.balance) AS total_balance,
    sum(
        CASE
            WHEN (ap.due_date >= CURRENT_DATE) THEN ap.balance
            ELSE (0)::numeric
        END) AS current_balance,
    sum(
        CASE
            WHEN ((ap.due_date < CURRENT_DATE) AND (ap.due_date >= (CURRENT_DATE - 30))) THEN ap.balance
            ELSE (0)::numeric
        END) AS days_1_30,
    sum(
        CASE
            WHEN ((ap.due_date < (CURRENT_DATE - 30)) AND (ap.due_date >= (CURRENT_DATE - 60))) THEN ap.balance
            ELSE (0)::numeric
        END) AS days_31_60,
    sum(
        CASE
            WHEN ((ap.due_date < (CURRENT_DATE - 60)) AND (ap.due_date >= (CURRENT_DATE - 90))) THEN ap.balance
            ELSE (0)::numeric
        END) AS days_61_90,
    sum(
        CASE
            WHEN (ap.due_date < (CURRENT_DATE - 90)) THEN ap.balance
            ELSE (0)::numeric
        END) AS days_over_90
   FROM (public.accounts_payable ap
     JOIN public.suppliers s ON ((ap.supplier_id = s.id)))
  WHERE ((ap.status)::text <> ALL ((ARRAY['PAID'::character varying, 'CANCELLED'::character varying])::text[]))
  GROUP BY s.id, s.fantasy_name, s.business_name, s.rut
 HAVING (sum(ap.balance) > (0)::numeric)
  ORDER BY (sum(ap.balance)) DESC;


--
-- Name: VIEW v_accounts_payable_aging; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_accounts_payable_aging IS 'Reporte de antigüedad de deuda por proveedor';


--
-- Name: v_accounts_payable_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_accounts_payable_summary AS
 SELECT ap.id,
    ap.invoice_number,
    ap.invoice_type,
    s.rut AS supplier_rut,
    COALESCE(s.fantasy_name, s.business_name) AS supplier_name,
    ap.issue_date,
    ap.due_date,
    ap.total_amount,
    ap.paid_amount,
    ap.balance,
    ap.status,
    ap.expense_category,
    l.name AS location_name,
        CASE
            WHEN ((ap.due_date < CURRENT_DATE) AND ((ap.status)::text <> ALL ((ARRAY['PAID'::character varying, 'CANCELLED'::character varying])::text[]))) THEN (CURRENT_DATE - ap.due_date)
            ELSE 0
        END AS days_overdue,
    ap.created_at
   FROM ((public.accounts_payable ap
     LEFT JOIN public.suppliers s ON ((ap.supplier_id = s.id)))
     LEFT JOIN public.locations l ON ((ap.location_id = l.id)))
  ORDER BY
        CASE ap.status
            WHEN 'OVERDUE'::text THEN 1
            WHEN 'PENDING'::text THEN 2
            WHEN 'PARTIAL'::text THEN 3
            ELSE 4
        END, ap.due_date;


--
-- Name: VIEW v_accounts_payable_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_accounts_payable_summary IS 'Vista resumen de cuentas por pagar con datos de proveedor';


--
-- Name: v_active_reconciliation_alerts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_active_reconciliation_alerts AS
 SELECT ra.id AS alert_id,
    ra.alert_type,
    ra.severity,
    ra.status AS alert_status,
    ra.created_at AS alert_created_at,
    cr.id AS reconciliation_id,
    cr.difference,
    cr.difference_type,
    cr.created_by AS cashier_id,
    cr.terminal_id,
    cr.location_id,
    cr.created_at AS reconciliation_date
   FROM (public.reconciliation_alerts ra
     JOIN public.cash_reconciliations cr ON ((ra.reconciliation_id = cr.id)))
  WHERE ((ra.status)::text = ANY ((ARRAY['OPEN'::character varying, 'ACKNOWLEDGED'::character varying])::text[]))
  ORDER BY
        CASE ra.severity
            WHEN 'CRITICAL'::text THEN 1
            WHEN 'HIGH'::text THEN 2
            WHEN 'MEDIUM'::text THEN 3
            ELSE 4
        END, ra.created_at DESC;


--
-- Name: v_ai_usage_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_usage_summary AS
 SELECT date_trunc('month'::text, created_at) AS month,
    provider,
    model,
    count(*) AS total_requests,
    sum(
        CASE
            WHEN success THEN 1
            ELSE 0
        END) AS successful_requests,
    sum(total_tokens) AS total_tokens,
    sum(estimated_cost) AS total_cost,
    avg(response_time_ms) AS avg_response_time_ms
   FROM public.ai_usage_log
  GROUP BY (date_trunc('month'::text, created_at)), provider, model
  ORDER BY (date_trunc('month'::text, created_at)) DESC, provider, model;


--
-- Name: VIEW v_ai_usage_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_ai_usage_summary IS 'Resumen mensual de uso de IA por proveedor y modelo';


--
-- Name: v_audit_chain_integrity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_audit_chain_integrity AS
 WITH chain_check AS (
         SELECT audit_log.id,
            audit_log.created_at,
            audit_log.checksum,
            audit_log.previous_checksum,
            lag(audit_log.checksum) OVER (ORDER BY audit_log.created_at, audit_log.id) AS expected_previous
           FROM public.audit_log
        )
 SELECT id,
    created_at,
    checksum,
    previous_checksum,
    expected_previous,
        CASE
            WHEN ((previous_checksum)::text = 'GENESIS_BLOCK'::text) THEN 'GENESIS'::text
            WHEN ((previous_checksum)::text = (expected_previous)::text) THEN 'VALID'::text
            WHEN (expected_previous IS NULL) THEN 'FIRST_AFTER_GENESIS'::text
            ELSE 'BROKEN_CHAIN'::text
        END AS chain_status
   FROM chain_check
  WHERE (((previous_checksum)::text <> (expected_previous)::text) AND ((previous_checksum)::text <> 'GENESIS_BLOCK'::text) AND (expected_previous IS NOT NULL));


--
-- Name: VIEW v_audit_chain_integrity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_audit_chain_integrity IS 'Detecta registros con cadena de integridad rota';


--
-- Name: v_cashier_reconciliation_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cashier_reconciliation_history AS
 SELECT created_by AS user_id,
    count(*) AS total_shifts,
    sum(
        CASE
            WHEN ((difference_type)::text = 'BALANCED'::text) THEN 1
            ELSE 0
        END) AS balanced_shifts,
    sum(
        CASE
            WHEN (difference < ('-1000'::integer)::numeric) THEN 1
            ELSE 0
        END) AS major_shortage_count,
    sum(
        CASE
            WHEN (difference > (1000)::numeric) THEN 1
            ELSE 0
        END) AS major_surplus_count,
    round(sum(difference), 2) AS net_difference,
    round(avg(difference), 2) AS avg_difference,
    round(stddev(difference), 2) AS stddev_difference,
    max(abs(difference)) AS max_absolute_difference,
    min(created_at) AS first_reconciliation,
    max(created_at) AS last_reconciliation
   FROM public.cash_reconciliations cr
  GROUP BY created_by;


--
-- Name: v_daily_audit_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_audit_summary AS
 SELECT date_trunc('day'::text, al.created_at) AS audit_date,
    al.location_id,
    count(*) AS total_actions,
    count(*) FILTER (WHERE ((ac.severity)::text = 'CRITICAL'::text)) AS critical_count,
    count(*) FILTER (WHERE ((ac.severity)::text = 'HIGH'::text)) AS high_count,
    count(*) FILTER (WHERE ((ac.category)::text = 'FINANCIAL'::text)) AS financial_actions,
    count(*) FILTER (WHERE ((ac.category)::text = 'SECURITY'::text)) AS security_actions,
    count(DISTINCT al.user_id) AS unique_users
   FROM (public.audit_log al
     JOIN public.audit_action_catalog ac ON (((al.action_code)::text = (ac.code)::text)))
  GROUP BY (date_trunc('day'::text, al.created_at)), al.location_id
  ORDER BY (date_trunc('day'::text, al.created_at)) DESC;


--
-- Name: v_invoice_parsings_pending; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_invoice_parsings_pending AS
 SELECT ip.id,
    ip.supplier_rut,
    ip.supplier_name,
    ip.document_type,
    ip.invoice_number,
    ip.issue_date,
    ip.total_amount,
    ip.confidence_score,
    ip.status,
    ip.total_items,
    ip.mapped_items,
    ip.unmapped_items,
    ip.created_at,
    u.name AS created_by_name,
    l.name AS location_name,
        CASE
            WHEN (ip.confidence_score >= 0.9) THEN 'HIGH'::text
            WHEN (ip.confidence_score >= 0.7) THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS confidence_level
   FROM ((public.invoice_parsings ip
     LEFT JOIN public.users u ON (((ip.created_by)::text = (u.id)::text)))
     LEFT JOIN public.locations l ON ((ip.location_id = l.id)))
  WHERE ((ip.status)::text = ANY ((ARRAY['PENDING'::character varying, 'VALIDATED'::character varying, 'MAPPING'::character varying])::text[]))
  ORDER BY
        CASE ip.status
            WHEN 'MAPPING'::text THEN 1
            WHEN 'VALIDATED'::text THEN 2
            ELSE 3
        END, ip.created_at DESC;


--
-- Name: VIEW v_invoice_parsings_pending; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_invoice_parsings_pending IS 'Facturas pendientes de procesar ordenadas por prioridad';


--
-- Name: v_problematic_reconciliations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_problematic_reconciliations AS
 SELECT id,
    session_id,
    terminal_id,
    location_id,
    difference,
    difference_type,
    status,
    created_at,
    created_by,
    COALESCE(( SELECT sum(rj.amount_justified) AS sum
           FROM public.reconciliation_justifications rj
          WHERE (rj.reconciliation_id = cr.id)), (0)::numeric) AS total_justified,
    (abs(difference) - COALESCE(( SELECT sum(rj.amount_justified) AS sum
           FROM public.reconciliation_justifications rj
          WHERE (rj.reconciliation_id = cr.id)), (0)::numeric)) AS pending_justification,
    ( SELECT count(*) AS count
           FROM public.reconciliation_alerts ra
          WHERE ((ra.reconciliation_id = cr.id) AND ((ra.status)::text = 'OPEN'::text))) AS open_alerts
   FROM public.cash_reconciliations cr
  WHERE (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'UNDER_INVESTIGATION'::character varying])::text[])) OR ((abs(difference) > (500)::numeric) AND (approved_at IS NULL)))
  ORDER BY (abs(difference)) DESC;


--
-- Name: v_reconciliation_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reconciliation_summary AS
 SELECT date_trunc('day'::text, created_at) AS date,
    location_id,
    count(*) AS total_reconciliations,
    sum(
        CASE
            WHEN ((difference_type)::text = 'BALANCED'::text) THEN 1
            ELSE 0
        END) AS balanced_count,
    sum(
        CASE
            WHEN ((difference_type)::text = 'SHORTAGE'::text) THEN 1
            ELSE 0
        END) AS shortage_count,
    sum(
        CASE
            WHEN ((difference_type)::text = 'SURPLUS'::text) THEN 1
            ELSE 0
        END) AS surplus_count,
    COALESCE(sum(
        CASE
            WHEN (difference < (0)::numeric) THEN difference
            ELSE (0)::numeric
        END), (0)::numeric) AS total_shortage,
    COALESCE(sum(
        CASE
            WHEN (difference > (0)::numeric) THEN difference
            ELSE (0)::numeric
        END), (0)::numeric) AS total_surplus,
    round(avg(abs(difference)), 2) AS avg_absolute_difference,
    count(*) FILTER (WHERE ((status)::text = 'PENDING'::text)) AS pending_count,
    count(*) FILTER (WHERE ((status)::text = 'UNDER_INVESTIGATION'::text)) AS under_investigation_count
   FROM public.cash_reconciliations cr
  GROUP BY (date_trunc('day'::text, created_at)), location_id
  ORDER BY (date_trunc('day'::text, created_at)) DESC;


--
-- Name: v_suspicious_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_suspicious_activity AS
 SELECT al.created_at,
    al.user_name,
    al.user_role,
    al.action_code,
    ac.description AS action_description,
    ac.severity,
    al.entity_type,
    al.entity_id,
    al.ip_address,
    al.justification,
    al.terminal_id,
    al.location_id,
    al.metadata
   FROM (public.audit_log al
     JOIN public.audit_action_catalog ac ON (((al.action_code)::text = (ac.code)::text)))
  WHERE ((ac.severity)::text = ANY ((ARRAY['HIGH'::character varying, 'CRITICAL'::character varying])::text[]))
  ORDER BY al.created_at DESC;


--
-- Name: VIEW v_suspicious_activity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_suspicious_activity IS 'Vista de acciones de alta severidad para revisión de seguridad';


--
-- Name: v_terminals_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_terminals_status AS
 SELECT t.id AS terminal_id,
    t.name AS terminal_name,
    t.status AS terminal_status,
    l.name AS location_name,
    l.id AS location_id,
    u.name AS cashier_name,
    u.id AS cashier_id,
    s.id AS session_id,
    s.opened_at AS session_start,
    s.opening_amount,
    (EXTRACT(epoch FROM (now() - (s.opened_at)::timestamp with time zone)) / (3600)::numeric) AS hours_open,
    t.is_active,
    t.deleted_at
   FROM (((public.terminals t
     LEFT JOIN public.locations l ON ((t.location_id = l.id)))
     LEFT JOIN public.users u ON (((t.current_cashier_id)::text = (u.id)::text)))
     LEFT JOIN public.cash_register_sessions s ON (((s.terminal_id = t.id) AND (s.status = 'OPEN'::text))))
  WHERE (t.deleted_at IS NULL)
  ORDER BY l.name, t.name;


--
-- Name: v_user_activity_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_activity_timeline AS
 SELECT al.user_id,
    al.user_name,
    date_trunc('day'::text, al.created_at) AS activity_date,
    al.action_code,
    ac.category,
    count(*) AS action_count
   FROM (public.audit_log al
     JOIN public.audit_action_catalog ac ON (((al.action_code)::text = (ac.code)::text)))
  WHERE (al.user_id IS NOT NULL)
  GROUP BY al.user_id, al.user_name, (date_trunc('day'::text, al.created_at)), al.action_code, ac.category
  ORDER BY (date_trunc('day'::text, al.created_at)) DESC, (count(*)) DESC;


--
-- Name: v_zombie_sessions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_zombie_sessions AS
 SELECT s.id,
    s.terminal_id,
    t.name AS terminal_name,
    s.user_id,
    u.name AS user_name,
    s.opened_at,
    (EXTRACT(epoch FROM (now() - (s.opened_at)::timestamp with time zone)) / (3600)::numeric) AS hours_open,
    s.status
   FROM ((public.cash_register_sessions s
     JOIN public.terminals t ON ((s.terminal_id = t.id)))
     LEFT JOIN public.users u ON (((s.user_id)::text = (u.id)::text)))
  WHERE ((s.status = 'OPEN'::text) AND ((s.opened_at < (now() - '12:00:00'::interval)) OR (s.opened_at IS NULL)))
  ORDER BY s.opened_at DESC;


